import { NextRequest } from 'next/server';
import { TABLE_REGISTRY } from '@/lib/tableRegistry';
import { dataGet, dataPost, dataPatch, dataDelete, dataNotFound } from '@/lib/dataRoute';

/* Support domain data route (GENERATED by the wire closure, 2026-11-15):
   the named API surface for the support tables that had no hand-written
   route. Tenant-scoped CRUD through the shared handler in
   lib/dataRoute.ts, driven by each table's TABLE_REGISTRY entry.
   Tables served here:
   - support_actions
   - support_attachments
   - support_case_details
   - support_categories
   - support_channels
   - support_contact_notes
   - support_contact_orgs
   - support_contacts
   - support_drafts
   - support_escalation_rules
   - support_forms
   - support_jobs
   - support_notification_prefs
   - support_notifications
   - support_oncall_participants
   - support_organizations
   - support_permissions
   - support_report_daily
   - support_side_conversation_messages
   - support_side_conversation_participants
   - support_side_conversations
   - support_signatures
   - support_staff_skills
   - support_templates
   - support_ticket_access_grants
   - support_ticket_counters
   - support_ticket_participants
   - support_ticket_relations
   - support_time_entries
   - support_webhook_deliveries
   - support_webhooks_outbound
*/

const SERVED = new Set([
  'support_actions',
  'support_attachments',
  'support_case_details',
  'support_categories',
  'support_channels',
  'support_contact_notes',
  'support_contact_orgs',
  'support_contacts',
  'support_drafts',
  'support_escalation_rules',
  'support_forms',
  'support_jobs',
  'support_notification_prefs',
  'support_notifications',
  'support_oncall_participants',
  'support_organizations',
  'support_permissions',
  'support_report_daily',
  'support_side_conversation_messages',
  'support_side_conversation_participants',
  'support_side_conversations',
  'support_signatures',
  'support_staff_skills',
  'support_templates',
  'support_ticket_access_grants',
  'support_ticket_counters',
  'support_ticket_participants',
  'support_ticket_relations',
  'support_time_entries',
  'support_webhook_deliveries',
  'support_webhooks_outbound'
]);

function entry(table: string) {
  return SERVED.has(table) ? TABLE_REGISTRY[table] ?? null : null;
}

export async function GET(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataGet(req, table, r) : dataNotFound(table);
}

export async function POST(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPost(req, table, r) : dataNotFound(table);
}

export async function PATCH(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPatch(req, table, r) : dataNotFound(table);
}

export async function DELETE(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataDelete(req, table, r) : dataNotFound(table);
}
